class FooBase(ABC):
    bar: str
    baz: int

    def __init__(self):
        self.bar = "bar"
        self.baz = 42

class FooProtocol(Protocol):
    foo: str

class Foo(FooBase, FooProtocol):
    foo: str = "hello"  # Required due to FooProtocol

